package com.mfg.wms.entity;
import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="wms_inventory",catalog="src_wms") @Getter @Setter @NoArgsConstructor public class Inventory{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="material_code")private String materialCode;@Column(name="material_name")private String materialName;@Column(name="warehouse_code")private String warehouseCode;@Column(name="location_code")private String locationCode;@Column(name="batch_no")private String batchNo;@Column(name="on_hand_qty")private BigDecimal onHandQty=BigDecimal.ZERO;@Column(name="allocated_qty")private BigDecimal allocatedQty=BigDecimal.ZERO;@Column(name="available_qty")private BigDecimal availableQty=BigDecimal.ZERO;@Column(name="unit_code")private String unitCode;@Column(name="unit_cost")private BigDecimal unitCost=BigDecimal.ZERO;@Column(name="total_cost")private BigDecimal totalCost=BigDecimal.ZERO;
@Column(name="in_transit_qty")private BigDecimal inTransitQty=BigDecimal.ZERO;
@Column(name="quality_status")private String qualityStatus="AVAILABLE";@Column(name="frozen_qty")private BigDecimal frozenQty=BigDecimal.ZERO;
@Column(name="received_date")private LocalDate receivedDate;@Column(name="last_in_date")private LocalDate lastInDate;@Column(name="last_out_date")private LocalDate lastOutDate;
@Column(name="updated_at")private LocalDateTime updatedAt;}
